<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:34377/breeze/NorthwindIBModel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
